document.addEventListener('keydown',e=>{if($('modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.code==='Space'){space=true;e.preventDefault();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('redo'):$('undo')).click();return;}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){pending=[];$('tool-menu').hidden=true;$('success').hidden=true;renderPreview();updateInstruction();announce('Selection cancelled.');}const keys={l:'line',e:'extend',c:'circle',h:'pan'};if(keys[e.key.toLowerCase()])setTool(keys[e.key.toLowerCase()]);if(e.key.toLowerCase()==='f'){sign*=-1;announce(`Earned constructions will use the ${sign===-1?'first':'opposite'} side.`);}if(e.key==='Enter'&&e.target===svg)check();});document.addEventListener('keyup',e=>{if(e.code==='Space')space=false;});window.addEventListener('blur',()=>{space=false;stopDrag();});
