const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_construction_game',description:'Read the current Euclid challenge, constructed geometry, and earned tools.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({proposition:isSandbox?null:activeId,challenge:isSandbox?'Free canvas':current().description,shapes,points:explicit,earnedTools:[...solved]})});register({name:'start_euclid_proposition',description:'Open a construction challenge by its exact proposition identifier.',inputSchema:{type:'object',properties:{id:{type:'string',enum:PROPOSITIONS.map(s=>s.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!known.has(input.id))throw Error('Unknown proposition');loadLevel(input.id);return{id:activeId,title:current().title};}});register({name:'check_euclid_construction',description:'Check current geometry and award its construction tool when solved.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(isSandbox)throw Error('Open a proposition first');return{complete:check(),earnedTools:[...solved]};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
window.addEventListener('resize',render);
// Load without saving an uninitialized board over the first challenge.
const first=setup(current());shapes=first.shapes;explicit=first.points;loadLevel(activeId);
